import React, { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./OtpVerification.css";

const OtpVerification = () => {
  const [otp, setOtp] = useState(["", "", "", ""]);
  const [error, setError] = useState("");
  const [timeLeft, setTimeLeft] = useState(300); // 5 minutes = 300 seconds
  const [expired, setExpired] = useState(false);

  const inputRefs = [useRef(), useRef(), useRef(), useRef()];
  const navigate = useNavigate();

      const liveURl = "https://immigrategpt.ca"
  // const liveURl = "http://localhost:5000"

  useEffect(() => {
    const token = localStorage.getItem("OTPVerified");
    const otpverify = localStorage.getItem("OTPVerified");
    if (token && otpverify) navigate("/c");
    // if (token) navigate("/c");
  }, [navigate]);

  // Countdown timer logic
  useEffect(() => {
    if (timeLeft <= 0) {
      setExpired(true);
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft]);

  const formatTime = (seconds) => {
    const m = Math.floor(seconds / 60)
      .toString()
      .padStart(2, "0");
    const s = (seconds % 60).toString().padStart(2, "0");
    return `${m}:${s}`;
  };

  const handleChange = (index, value) => {
    if (/^\d?$/.test(value)) {
      const newOtp = [...otp];
      newOtp[index] = value;
      setOtp(newOtp);

      if (value && index < 3) {
        inputRefs[index + 1].current.focus();
      }
    }
  };

  const handleKeyDown = (index, e) => {
    if (e.key === "Backspace" && !otp[index] && index > 0) {
      inputRefs[index - 1].current.focus();
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (expired) {
      setError("OTP has expired. Please go back and try again.");
      return;
    }

    const fullOtp = otp.join("");

    if (fullOtp.length !== 4) {
      setError("Please enter all 4 digits.");
      return;
    }

    const userEmail = localStorage.getItem("userEmail");
    if (!userEmail) {
      setError("Email not found. Please sign up again.");
      return;
    }

    try {
      const response = await axios.post(
        `${liveURl}/api/auth/verify-otp`,
        {
          email: userEmail,
          otp: fullOtp,
        }
      );

      localStorage.setItem("OTPVerified", true);
      console.log("OTP Verified", response.data);
      navigate("/c");
    } catch (error) {
      setError(error.response?.data?.message || "Invalid OTP");
    }
  };

  const handleResendOtp = async () => {
    const userEmail = localStorage.getItem("userEmail");

    if (!userEmail) {
      setError("Email not found. Please sign up again.");
      return;
    }

    try {
      const response = await axios.post(
        `${liveURl}/api/auth/resend-otp`,
        {
          email: userEmail,
        }
      );

      console.log("OTP Resent:", response.data.message);
      setOtp(["", "", "", ""]); // Clear existing input
      setTimeLeft(300); // Reset timer
      setExpired(false); // Reactivate form
      setError(""); // Clear any errors
      inputRefs[0].current.focus(); // Focus first input
    } catch (err) {
      setError(err.response?.data?.message || "Failed to resend OTP");
    }
  };

  return (
    <div className="otp-container">
      <div className="otp-box">
        <h2>Enter OTP</h2>
        {error && <p className="error-msg">{error}</p>}

        <p className="timer">Time Remaining: {formatTime(timeLeft)}</p>

        <form onSubmit={handleSubmit}>
          <div className="otp-inputs">
            {otp.map((digit, index) => (
              <input
                key={index}
                type="text"
                value={digit}
                onChange={(e) => handleChange(index, e.target.value)}
                onKeyDown={(e) => handleKeyDown(index, e)}
                ref={inputRefs[index]}
                maxLength="1"
                pattern="[0-9]"
                className="otp-input"
                disabled={expired}
              />
            ))}
          </div>

          <button type="submit" className="verify-btn" disabled={expired}>
            Verify
          </button>
        </form>

        {expired && (
          <>
            <button className="resend-btn" onClick={handleResendOtp}>
              Resend OTP
            </button>
            <p className="expired-msg">
              OTP expired. Please request a new one.
            </p>
          </>
        )}
      </div>

      <p className="developed-by">Developed by ParamSolutions</p>
    </div>
  );
};

export default OtpVerification;
