import React from "react";
import "./WaitingList.css";

const WaitingList = () => {
  return (
    <div className="waitlist-container">
      <div className="waitlist-card">
        <h1>Thank you for choosing <span className="brand">ImmigrateGPT</span>!</h1>
        <p className="message">
          Due to high demand, our free version is currently available by invitation only.
        </p>
        <p className="message highlight">
          👉 Join the waitlist today and we’ll send you an invite as soon as a spot opens up.
        </p>
        <p className="message">
          If you’d like immediate access to ImmigrateGPT, you can get started right away with our <strong>Premium Plan</strong> — enjoy priority support and the full power of ImmigrateGPT without waiting.
        </p>

        <div className="button-group">
          {/* <button className="btn btn-waitlist" onClick={() => window.location.href = "/join-waitlist"}>Join the Waitlist</button> */}
          <button className="btn btn-premium" onClick={() => window.location.href = "/upgradeplans"}>Upgrade to Premium</button>
        </div>
      </div>
    </div>
  );
};

export default WaitingList;
