
import "./KeyboardShortcutPopup.css";
import React, { useEffect } from "react";

const shortcuts = [
  { keys: "ctrl + q", description: "Search chats" },
  { keys: "ctrl + shift + a", description: "Open new chat" },
  { keys: "ctrl + shift + b", description: "Toggle sidebar" },
  { keys: "ctrl + z", description: "Share current opened chat" },
  { keys: "ctrl + shift + f", description: "Focus input chat" },
];

export default function KeyboardShortcutsPopup({ isOpen, onClose }) {
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === "Escape") {
        onClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [onClose]);

  if (!isOpen) return null;

  return (
    <div
      className="shortcuts-modal"
      role="dialog"
      aria-modal="true"
      aria-labelledby="shortcuts-title"
      onClick={onClose} // close when clicking outside content
    >
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <button
          className="shortcuts-close-btn"
          aria-label="Close keyboard shortcuts"
          onClick={onClose}
          type="button"
        >
          ×
        </button>
        <h2 id="shortcuts-title">Keyboard Shortcuts</h2>
        <ul>
          {shortcuts.map(({ keys, description }, i) => (
            <li key={i}>
              <kbd className="key">{keys}</kbd>
              <span>{description}</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
