import React, { useState, useEffect, useRef, useMemo } from "react";
import { FiPlus, FiSearch, FiX, FiTrash } from "react-icons/fi";
import { FiArrowLeft } from "react-icons/fi";
import { useNavigate, useLocation } from "react-router-dom";
import "./ApplyTestPage.css";
import toast from "react-hot-toast";

export default function ApplyTestPage() {
  const [selectedTopic, setSelectedTopic] = useState("immigration");
  const [testData, setTestData] = useState({});
  const questions = useMemo(
    () => testData[selectedTopic] || [],
    [testData, selectedTopic]
  );

      const liveURl = "https://immigrategpt.ca"
  // const liveURl = "http://localhost:5000"

  // const questions = testData[selectedTopic] || [];
  //   const questions = testData[selectedTopic] || [];
  const [currentQ, setCurrentQ] = useState(0);
  const [selected, setSelected] = useState(null);
  const [score, setScore] = useState(0);
  const [submitted, setSubmitted] = useState(false);
  const [chats, setChats] = useState([]); // optional dummy data
  // Sidebar-related state
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [filteredChats, setFilteredChats] = useState(chats);
  const [showSearch, setShowSearch] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [currentChatId, setCurrentChatId] = useState(null);
  const navigate = useNavigate();
  const location = useLocation();
  //   const [testStarted, setTestStarted] = useState(false);
  const [startedTopics, setStartedTopics] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef(null);
  const testStarted = startedTopics[selectedTopic] || false;

  // const [userAnswers, setUserAnswers] = useState(
  //   Array(questions.length).fill(null)
  // );
  const [userAnswers, setUserAnswers] = useState([]);
  useEffect(() => {
    setUserAnswers(Array(questions.length).fill(null));
  }, [questions]);

  const startTest = () => {
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setStartedTopics((prev) => ({ ...prev, [selectedTopic]: true }));
    }, 3000);
  };

  // const changeTopic = (topic) => {
  //   setSelectedTopic(topic);
  //   setCurrentQ(0);
  //   setSelected(null);
  //   setScore(0);
  //   setSubmitted(false);
  //   setIsLoading(false);
  // };
  const changeTopic = (topic) => {
    if (testStarted && topic !== selectedTopic) {
      const confirmReset = window.confirm(
        "You are in the middle of a test. Switching topics will reset your progress. Do you want to continue?"
      );
      if (!confirmReset) return;

      toast("Previous test was reset. You switched topics.");
    }

    setSelectedTopic(topic);
    setCurrentQ(0);
    setSelected(null);
    setScore(0);
    setSubmitted(false);
    setIsLoading(false);

    setStartedTopics((prev) => ({
      ...prev,
      [selectedTopic]: false,
    }));
  };

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    setSelected(userAnswers[currentQ]);
  }, [currentQ]);

  // const handleNext = () => {
  //   if (selected === questions[currentQ].answer) {
  //     setScore(score + 1);
  //   }

  //   if (currentQ + 1 < questions.length) {
  //     setCurrentQ(currentQ + 1);
  //     setSelected(null);
  //   } else {
  //     setSubmitted(true);
  //   }
  // };
  const handleNext = () => {
    if (currentQ + 1 < questions.length) {
      setCurrentQ(currentQ + 1);
      setSelected(null);
    } else {
      // Submit and calculate final score
      const calculatedScore = userAnswers.reduce((total, answer, index) => {
        return answer === questions[index].answer ? total + 1 : total;
      }, 0);
      setScore(calculatedScore);
      setSubmitted(true);
    }
  };

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth <= 767) {
        setIsSidebarOpen(false);
      } else {
        setIsSidebarOpen(true);
      }
    };

    window.addEventListener("resize", handleResize);
    handleResize(); // Initial check

    return () => window.removeEventListener("resize", handleResize);
  }, []);

  useEffect(() => {
    // fetch("http://localhost:5000/test/api/testdata")
    fetch(`${liveURl}/api/examination/testdata`)
    // fetch("https://immigrategpt.ca/api/examination/testdata")
      .then((res) => res.json())
      .then((data) => {
        console.log("Fetched test data:", data); // ✅ Console log here
        setTestData(data);
      })
      .catch((err) => {
        console.error("Error loading test data:", err);
      });
  }, []);

  return (
    <div className="app-layout">
      {/* SIDEBAR */}
      <aside className={`sidebar2 ${isSidebarOpen ? "open" : "collapsed"}`}>
        <div className="sidebar2-header">
          <button
            className="toggle-btn2"
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          >
            ☰
          </button>
          {isSidebarOpen && (
            <>
              <button className="new-chat-btn2" onClick={() => navigate("/c")}>
                <FiArrowLeft className="arrowleft-icon" />
              </button>
            </>
          )}
        </div>

        {/* {isSidebarOpen && (
          <div className="chat-history2">
            <div
              className={`chat-item2 ${
                selectedTopic === "immigration" ? "active" : ""
              }`}
              onClick={() => changeTopic("immigration")}
            >
              <div className="chat-title2">📝 Canada's Immigration Tests</div>
            </div>
            <div
              className={`chat-item2 ${
                selectedTopic === "canada study permit" ? "active" : ""
              }`}
              onClick={() => changeTopic("canada study permit")}
            >
              <div className="chat-title2">📝 Study Permit Tests</div>
            </div>
            <div
              className={`chat-item2 ${
                selectedTopic === "work" ? "active" : ""
              }`}
              onClick={() => changeTopic("work")}
            >
              <div className="chat-title2">📝 Work Permit Tests</div>
            </div>
          </div>
        )} */}
        {isSidebarOpen && (
  <div className="chat-history2">
    {Object.keys(testData).map((topic) => (
      <div
        key={topic}
        className={`chat-item2 ${selectedTopic === topic ? "active" : ""}`}
        onClick={() => changeTopic(topic)}
      >
        <div className="chat-title2">
          📝{" "}
          {topic
            .split(" ")
            .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
            .join(" ")}
        </div>
      </div>
    ))}
  </div>
)}

      </aside>

      {/* MAIN TEST AREA */}
      <main className="main-content">
        {!testStarted ? (
          <div className="test-container center">
            <h2 className="topic-heading">
              🧪{" "}
              {selectedTopic.charAt(0).toUpperCase() + selectedTopic.slice(1)}{" "}
              Test
            </h2>

            {!isLoading ? (
              <button className="start-btn" onClick={startTest}>
                Start Test
              </button>
            ) : (
              <div className="loader">Loading...</div>
            )}
          </div>
        ) : submitted ? (
          <div className="test-container">
            <h2>Test Complete ✅</h2>
            <p>
              You scored <strong>{score}</strong> out of {questions.length}
            </p>
          </div>
        ) : (
          <div className="test-container">
            <h2>
              🧪{" "}
              {selectedTopic.charAt(0).toUpperCase() + selectedTopic.slice(1)}{" "}
              Test
            </h2>
            <p>
              <strong>Q{currentQ + 1}:</strong> {questions[currentQ].question}
            </p>
            <ul className="options">
              {questions[currentQ].options.map((opt) => (
                <li
                  key={opt}
                  className={selected === opt ? "selected" : ""}
                  // onClick={() => setSelected(opt)}
                  onClick={() => {
                    setSelected(opt);
                    const updatedAnswers = [...userAnswers];
                    updatedAnswers[currentQ] = opt;
                    setUserAnswers(updatedAnswers);
                  }}
                >
                  {opt}
                </li>
              ))}
            </ul>

            <div className="navigation-buttons">
              {currentQ > 0 && (
                <button
                  onClick={() => {
                    setCurrentQ(currentQ - 1);
                    setSelected(null);
                  }}
                >
                  Previous
                </button>
              )}
              <button disabled={!selected} onClick={handleNext}>
                {currentQ + 1 === questions.length ? "Submit" : "Next"}
              </button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

