import React from "react";
import { useState } from "react";
import "./Home.css";
import { useNavigate } from "react-router-dom";
import { FiMenu, FiX } from "react-icons/fi";
import logopng from "../../../assets/logo.png";
import canadapng from "../../../assets/Flag_of_Canada_(Pantone).png";
import homescreenpng from "../../../assets/c07c6e2d-37b3-4ddf-9032-fbc45d9a1775.png";
import male from "../../../assets/male1.png";
import female from "../../../assets/female.png";
import WomenScene from "./WomenScene";

function Home() {
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);

  const move = () => {
    navigate("/login");
  };

  const movetohome = () => {
    navigate("/home");
  };
  return (
    <>
    
    <WomenScene/>
    <div className="home-container">
      {/* Navbar */}
      <section className="hero">
        <nav className="navbar">
          <div className="navbar-left">
            <img
              src={logopng}
              alt="Logo"
              className="navbar-logo"
              onClick={movetohome}
            />
          </div>

          <ul className="navbar-desktop-links">
            <li>
              <a href="/other-info">Other Info</a>
            </li>
            <li>
              <a href="/signup">Register</a>
            </li>
          </ul>

          {!menuOpen && (
            <FiMenu
              className="navbar-menu"
              size={24}
              onClick={() => setMenuOpen(true)}
            />
          )}
        </nav>

        {/* Slide-in links container over right 50% */}
        <div className={`navbar-links-container ${menuOpen ? "open" : ""}`}>
          <ul className="navbar-links">
            <li>
              <a href="/other-info">Other Info</a>
            </li>
            <li>
              <a href="/signup">Register</a>
            </li>

            <li>
              <FiX
                className="close-icon"
                size={24}
                onClick={() => setMenuOpen(false)}
              />
            </li>
          </ul>
        </div>
        

        {/* Rest of hero section */}
        <div className="hero-left">
          <h1>
            <img src={canadapng} alt="canada" className="canada-logo" />{" "}
            Canada’s First <br />
            <span>AI Immigration Assistant</span> <br />
            for International Students
          </h1>
          <p className="ptag">
            SOP with a PR planning, visa questions – solved instantly. Built by
            immigrants, powered by AI, just $5/month.
          </p>
          <button className="cta-button" onClick={move}>
            Get Access Now
          </button>
          <ul className="features-list">
            <li>✓ Trained on IRCC resources</li>
            <li>✓ Proudly Canadian Immigrant owned</li>
            <li>✓ Hosted securely in Canada</li>
          </ul>
        </div>

        <div className="hero-right">
          <div className="hero-image-placeholder">
            <img
              src={homescreenpng}
              alt="AI Immigration Assistant"
              className="hero-image"
            />
          </div>
        </div>
      </section>

      {/* What is Section */}
      <section className="what-is">
        <div className="what-left">
          <h2>What is ImmigrateGPT?</h2>
          <p className="ptag">
            <b>
              ImmigrateGPT is your 24/7 AI assistant built only for Canadian
            </b>{" "}
            immigration.
          </p>
          <ul>
            <li>✓ Trained on Canadian immigration rules</li>
            <li>✓ Answers your questions on latest rules</li>
            <li>✓ Keeps your data private (hosted in Canada)</li>
          </ul>
        </div>
        <div className="what-right">
          <div className="what-box">
            <strong>
              ImmigrateGPT is your 24/7 AI assistant built only for Canadian
              Immigration.
            </strong>
            <p className="ptag">
              Unlike ChatGPT or Google, our chatbot:
              <ul>
                <li>✓ One stop solution on latest immigration rules</li>
                {/* <li>✓ Helps you avoid visa auxy work</li> */}
                <li>✓ Gain better understand by answering questions</li>
              </ul>
            </p>
          </div>
        </div>
      </section>

      {/* Testimonials */}
      <section className="testimonials">
        <h2 className="testimonials-title">Testimonials</h2>
        <div className="testimonial-grid">
          <div className="testimonial-item">
            <div className="testimonial-card">
              <p className="testimonial-quote">
                “ImmigrateGPT helped me understand the study visa rules and also
                helped me increase my knowledge on immigration pathway.”
              </p>
            </div>
            <div className="testimonial-author-wrapper">
              <img src={male} alt="Sahil" className="testimonial-avatar" />
              <div className="testimonial-author">Sahil – India</div>
            </div>
          </div>
          <div className="testimonial-item">
            <div className="testimonial-card">
              <p className="testimonial-quote">
                “Way better than paying $$$ to a consultant for a small query.”
              </p>
            </div>
            <div className="testimonial-author-wrapper">
              <img src={female} alt="Fatima" className="testimonial-avatar" />
              <div className="testimonial-author">
                Fatima – Conestoga College
              </div>
            </div>
          </div>
          <div className="testimonial-item">
            <div className="testimonial-card">
              <p className="testimonial-quote">
                “I was able to plan my PR pathway in 10 minutes.”
              </p>
            </div>
            <div className="testimonial-author-wrapper">
              <img src={male} alt="Jing" className="testimonial-avatar" />
              <div className="testimonial-author">Jing – SAIT</div>
            </div>
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="faq">
        <h2>FAQ</h2>
        <div className="faq-grid">
          <div className="faq-item">
            How much do you charge? <br /> $5/month.
          </div>
          <div className="faq-item">
            Do I get a free trial? <br /> Yes free service will allow you to
            chat with the bot for 100 words a day.
          </div>
          <div className="faq-item">
            Can I cancel my subscription anytime? <br /> Yes, you are free to
            cancel your subscription.
          </div>
          <div className="faq-item">
            Where is my data stored? <br /> It is stored in Canada.{" "}
          </div>
        </div>

        {/* Move CTA inside FAQ */}
        <div className="faq-cta">
          <button className="cta-button full" onClick={move}>
            Start using ImmigrateGPT today
          </button>
        </div>
      </section>

      {/* Pricing Section */}
      <section className="pricing-section">
        <h2 className="pricing-title">Pricing</h2>
        <div className="pricing-cards">
          <div className="pricing-card">
            <h3>Free Plan</h3>
            <p>✓ 10 questions per day</p>
            <p>✓ Access to basic immigration questions</p>
            <p>✓ No payment required</p>
          </div>
          <div className="pricing-card premium">
            <h3>Premium Plan</h3>
            <p>✓ Unlimited questions</p>
            <p>✓ In-depth SOP and PR planning support</p>
            <p>✓ Only $5/month</p>
          </div>
        </div>
      </section>

      <footer className="footer-text">Developed by ParamSolutions.ca</footer>
    </div>
    </>
  );
}

export default Home;
