// src/pages/ResetPassword.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { useParams } from "react-router-dom";
import "./ResetPassword.css"; // Make sure this is created
import loginIllustration from "../../assets/login-illustration.webp";

const ResetPassword = () => {
  const navigate = useNavigate();
  const { token } = useParams();
  const [password, setPassword] = useState("");
  const [msg, setMsg] = useState("");
  const [error, setError] = useState("");
      const liveURl = "https://immigrategpt.ca"
  // const liveURl = "http://localhost:5000"

  const handleReset = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post(`${liveURl}/api/auth/reset-password/${token}`, { password });
      setMsg(res.data.message);
      setError("");
      navigate("/login");
    } catch (err) {
      setMsg("");
      setError(err.response?.data?.message || "Failed to reset password.");
    }
  };

  return (
    <div className="resetpassword-container">
      {/* Left Side - Form */}
      <div className="resetpassword-box">
        <h2>Reset Password</h2>
        <form onSubmit={handleReset}>
          <div className="resetpassword-input-group">
            <label htmlFor="password">New Password</label>
            <input
              type="password"
              id="password"
              placeholder="Enter your new password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          <button className="resetpassword-btn" type="submit">
            Update Password
          </button>
        </form>
        {msg && <p className="resetpassword-success">{msg}</p>}
        {error && <p className="resetpassword-error">{error}</p>}
      </div>

      {/* Right Side - Image & Info */}
      <div className="resetpassword-info">
        <h1>Update Your Password</h1>
        <p>Enter a new password to secure your account again.</p>
        <img src={loginIllustration} alt="Reset password illustration" />
      </div>
    </div>
  );
};

export default ResetPassword;
