import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";

const OauthSuccess = () => {
  const navigate = useNavigate();

  useEffect(() => {
    // Get token and plan from URL
    const params = new URLSearchParams(window.location.search);
    const token = params.get("token");
    const plan = params.get("plan");
    const email = params.get("email")

    if (token) {
        console.log("hello")
      // Save token and dummy email if needed (you could also return email from backend)
      localStorage.setItem("authToken", token);
      localStorage.setItem("userPlan", plan);
      localStorage.setItem("OTPVerified", true); // Optional: to align with your redirect logic
      localStorage.setItem("userEmail", email); // Optional: to align with your redirect logic

      // Navigate to dashboard or wherever
      navigate("/c");
    } else {
      // If no token, redirect back to signup
      navigate("/signup");
    }
  }, [navigate]);

  return <p>Redirecting...</p>;
};

export default OauthSuccess;
