import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./Login.css"; // Updated CSS
import loginIllustration from "../assets/login-illustration.webp";
import { FiEye, FiEyeOff } from "react-icons/fi";
import { FaGoogle, FaLinkedin, FaFacebook } from "react-icons/fa";
import ReCAPTCHA from "react-google-recaptcha";

const Login = () => {
  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });

      const liveURl = "https://immigrategpt.ca"
  // const liveURl = "http://localhost:5000"

  const [error, setError] = useState("");
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);

  const [recaptchaToken, setRecaptchaToken] = useState(null);

  const [fieldErrors, setFieldErrors] = useState({
    email: "",
    password: "",
    captcha: "",
  });

  // 🔥 Check if user is already logged in
  useEffect(() => {
    const token = localStorage.getItem("userEmail");
    // const otpverify = localStorage.getItem("OTPVerified");
    if (token) {
      navigate("/c"); // Redirect to dashboard or home page
    }
  }, [navigate]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Clear all previous errors
    setError("");
    setFieldErrors({
      email: "",
      password: "",
      captcha: "",
    });

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const errors = {};

    if (!formData.email.trim()) {
      errors.email = "Email is required.";
    } else if (!emailRegex.test(formData.email)) {
      errors.email = "Please enter a valid email address.";
    }

    if (!formData.password.trim()) {
      errors.password = "Password is required.";
    } else if (formData.password.length < 6) {
      errors.password = "Password must be at least 6 characters.";
    }

    if (!recaptchaToken) {
      errors.captcha = "Please complete the CAPTCHA.";
    }

    if (Object.keys(errors).length > 0) {
      setFieldErrors(errors);
      return;
    }

    try {
      const response = await axios.post(
        `${liveURl}/api/auth/login`,
        formData,
        recaptchaToken // ⬅️ Include this
      );
      localStorage.setItem("authToken", response.data.token);
      localStorage.setItem("userEmail", formData.email);
      const userResponse = await axios.get(
        `${liveURl}/api/auth/user`,
        {
          headers: {
            Authorization: `Bearer ${response.data.token}`,
          },
        }
      );

      const userPlan = userResponse.data.plan || "Free";
      // const userPlan = userResponse.data.plan;
      localStorage.setItem("userPlan", userPlan);

      navigate("/c");
    } catch (error) {
      if (error.response) {
        setError(
          error.response.data.message || "Login failed. Please try again."
        );
      } else if (error.request) {
        setError(
          "No response from server. Please check your internet connection."
        );
      } else {
        setError("An unexpected error occurred.");
      }
    }
  };

  return (
    <div className="login-container">
      {/* Left Side - Login Form */}
      <div className="login-box">
        <h2>Log In</h2>
        {error && <p className="error-msg">{error}</p>}
        <form onSubmit={handleSubmit}>
          {/* Email */}
          <div className="input-group">
            <label>Email</label>
            <input
              type="email"
              name="email"
              placeholder="Enter your email"
              value={formData.email}
              onChange={handleChange}
              required
            />
            {fieldErrors.email && (
              <p className="field-error">{fieldErrors.email}</p>
            )}
          </div>

          {/* Password */}
          <div className="input-group password-group">
            <label>Password</label>
            <div className="password-wrapper">
              <input
                type={showPassword ? "text" : "password"}
                name="password"
                placeholder="Enter your password"
                value={formData.password}
                onChange={handleChange}
                required
              />
              <span
                className="toggle-password"
                onClick={() => setShowPassword((prev) => !prev)}
              >
                {showPassword ? <FiEyeOff /> : <FiEye />}
              </span>
            </div>
            {fieldErrors.password && (
              <p className="field-error">{fieldErrors.password}</p>
            )}
          </div>

          {/* CAPTCHA */}
          <ReCAPTCHA
            sitekey="6LeNsnsrAAAAAKHoSgGLz5SS_TPRYfF2J39RrlLM"
            onChange={(token) => setRecaptchaToken(token)}
            className="recaptcha"
          />
          {fieldErrors.captcha && (
            <p className="field-error">{fieldErrors.captcha}</p>
          )}

          <button type="submit" className="login-btn">
            Log In
          </button>

          <p className="forgot-password-link">
            <a href="/forgot-password">Forgot Password?</a>
          </p>

          <p className="login-link">
            Not have any account? <a href="/signup">Sign Up</a>
          </p>
        </form>

        <div className="social-login">
          <button
            className="google-btn"
            onClick={
              () =>
                (window.location.href =
                  "https://www.immigrategpt.ca/api/auth/google")
              // (window.location.href = "http://localhost:5000/api/auth/google")
            }
            title="Login with Google"
          >
            <FaGoogle size={20} />
          </button>

          <button
            className="linkedin-btn"
            onClick={
              () =>
                (window.location.href =
                  "https://www.immigrategpt.ca/api/auth/linkedin")
              // (window.location.href = "https://immigrategpt.ca/api/auth/linkedin")
            }
            title="Login with LinkedIn"
          >
            <FaLinkedin size={20} />
          </button>

          <button
            className="facebook-btn"
            onClick={
              () =>
                (window.location.href =
                  "https://www.immigrategpt.ca/api/auth/facebook")
              // (window.location.href = "http://loscalhost:5000/api/auth/facebook")
            }
            title="Login with Facebook"
          >
            <FaFacebook size={20} />
          </button>
        </div>
      </div>

      <p className="developed-by">Developed by ParamSolutions.ca</p>

      {/* Right Side - Image & Text */}
      <div className="login-info">
        <h1>Welcome to AI Chat</h1>
        <p>
          Join now and start your journey with our AI-powered chat experience.
        </p>
        <img src={loginIllustration} alt="Chat AI Illustration" />
      </div>
    </div>
  );
};

export default Login;
