import React, { useRef, useEffect } from 'react';
import { useGLTF, useAnimations } from '@react-three/drei';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';

export function Model({ scrollPercent, yPosition = -2.25 }) {
  const group = useRef();
  const lastScroll = useRef(scrollPercent);
  const targetRotation = useRef(1.5); // default facing right
  const currentRotation = useRef(1.5);
  const scrollTimeout = useRef(null);
  const isScrolling = useRef(false);
  const wasScrolling = useRef(false);

  const { nodes, materials, animations } = useGLTF('/male_phone_walking_40_frames_loop.glb');
  const { actions } = useAnimations(animations, group);

  const walkAction = useRef(null);

  useEffect(() => {
    if (actions && animations.length > 0) {
      walkAction.current = actions[animations[0].name];
      walkAction.current.play(); // default playing
    }
  }, [actions, animations]);

  useEffect(() => {
    // detect user is scrolling
    isScrolling.current = true;
    clearTimeout(scrollTimeout.current);
    scrollTimeout.current = setTimeout(() => {
      isScrolling.current = false;
    }, 500); // 500ms after no scroll = stop
  }, [scrollPercent]);

  useFrame(() => {
    const model = group.current;
    if (!model) return;

    // Scroll to X position
    const minX = -4.5;
    const maxX = 4.5;
    const x = minX + scrollPercent * (maxX - minX);
    model.position.x = x;
    model.position.y = yPosition;

    // Detect scroll direction
    const delta = scrollPercent - lastScroll.current;
    const scrollingDown = delta > 0.0001;
    const scrollingUp = delta < -0.0001;
    lastScroll.current = scrollPercent;

    // Flip at ends
    const atLeft = scrollPercent <= 0.01;
    const atRight = scrollPercent >= 0.99;
    if (atLeft) {
      targetRotation.current = 1.5;
    } else if (atRight) {
      targetRotation.current = -1.5;
    } else if (scrollingDown || scrollingUp) {
      targetRotation.current = scrollingDown ? 1.5 : -1.5;
    }

    // Smooth rotation
    currentRotation.current = THREE.MathUtils.lerp(
      currentRotation.current,
      targetRotation.current,
      0.05
    );
    model.rotation.y = currentRotation.current;

    // Play or pause animation based on scroll activity
    if (walkAction.current) {
      if (isScrolling.current && !wasScrolling.current) {
        walkAction.current.paused = false;
        wasScrolling.current = true;
      } else if (!isScrolling.current && wasScrolling.current) {
        walkAction.current.paused = true;
        wasScrolling.current = false;
      }
    }
  });

  return (
    <group ref={group} dispose={null}>
      <group name="Sketchfab_Scene">
        <group name="Sketchfab_model" rotation={[-Math.PI / 2, 0, 0]}>
          <group name="locom_m_phoneWalking_40ffbx" rotation={[Math.PI / 2, 0, 0]} scale={0.01}>
            <group name="Object_2">
              <group name="RootNode">
                <group name="lpMaleG" rotation={[-Math.PI / 2, 0, 0]} />
                <group name="rig_CharRoot" rotation={[-Math.PI / 2, 0, 0]}>
                  <group name="Object_6">
                    <primitive object={nodes._rootJoint} />
                    <skinnedMesh
                      name="Object_9"
                      geometry={nodes.Object_9.geometry}
                      material={materials.peopleColors}
                      skeleton={nodes.Object_9.skeleton}
                    />
                    <group name="Object_8" rotation={[-Math.PI / 2, 0, 0]} />
                  </group>
                </group>
              </group>
            </group>
          </group>
        </group>
      </group>
    </group>
  );
}

useGLTF.preload('/male_phone_walking_40_frames_loop.glb');
