import React, { useEffect, useRef, useState } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import "./Chatstandalone.css";
import sidebarimg from "../assets/sidebar_logo.png";

// import { useNavigate } from "react-router-dom";
import { FiTrash, FiPlus } from "react-icons/fi";
import toast from "react-hot-toast";
import { FiX, FiSearch } from "react-icons/fi";
// import { color } from "framer-motion";
import { FiSend, FiMic } from "react-icons/fi";
import themes from "./theme"; // adjust path as needed

const Chatstandalone = () => {
  const { chatId: sharedId } = useParams();
  const [isSharedChat, setIsSharedChat] = useState(!!sharedId);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [showSearch, setShowSearch] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [filteredChats, setFilteredChats] = useState([]);
  const [currentChatId, setCurrentChatId] = useState(sharedId); // sync with current chat
  const [chat, setChat] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [messageInput, setMessageInput] = useState("");
  const [userMessageCount, setUserMessageCount] = useState(0);
  const [isTyping, setIsTyping] = useState(false);
  const [isAtBottom, setIsAtBottom] = useState(true);
  const messagesEndRef = useRef(null);
  const chatContainerRef = useRef(null);
  const [chats, setChats] = useState([]);

  const liveURl = "https://immigrategpt.ca"
  // const liveURl = "http://localhost:5000";

  useEffect(() => {
    if (!sharedId) {
      setIsSharedChat(false); // if URL param is missing, it's not a shared chat
    } else if (sharedId !== currentChatId) {
      setIsSharedChat(false); // moved away from shared chat
    } else {
      setIsSharedChat(true); // still in shared chat
    }
  }, [sharedId, currentChatId]);

  useEffect(() => {
    scrollToBottom();
  }, [chat?.messages]);

  useEffect(() => {
    const savedChats = localStorage.getItem("chats");
    if (savedChats) {
      setChats(JSON.parse(savedChats));
    }
  }, []);

  useEffect(() => {
    const container = chatContainerRef.current;
    if (!container) return;

    const handleScroll = () => {
      const { scrollTop, scrollHeight, clientHeight } = container;
      setIsAtBottom(scrollTop + clientHeight >= scrollHeight - 10);
    };

    container.addEventListener("scroll", handleScroll);
    return () => container.removeEventListener("scroll", handleScroll);
  }, []);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  // Get system theme preference (light or dark)
  const getSystemTheme = () => {
    return window.matchMedia("(prefers-color-scheme: dark)").matches
      ? "dark"
      : "light";
  };

  // const [theme, setTheme] = useState(localStorage.getItem("theme") || "system");
  const [theme, setTheme] = useState(() => {
    const storedTheme = localStorage.getItem("theme");
    if (storedTheme === "system") {
      return getSystemTheme(); // resolves to "light" or "dark"
    }
    return storedTheme || "dark"; // default to light if nothing stored
  });

  // Function to change the theme
  const onThemeChange = (newTheme) => {
    setTheme(newTheme);
    localStorage.setItem("theme", newTheme); // Save the theme preference to localStorage
  };

  // Apply the selected theme using CSS variables
  useEffect(() => {
    const effectiveTheme = theme === "system" ? getSystemTheme() : theme;
    const themeVars = themes[effectiveTheme];

    if (themeVars) {
      for (const key in themeVars) {
        document.documentElement.style.setProperty(key, themeVars[key]);
      }
      // Also update data-theme attribute (optional but useful for CSS)
      document.documentElement.setAttribute("data-theme", effectiveTheme);
    }
  }, [theme]);

  const openChat = (chatId) => {
    setCurrentChatId(chatId); // Set the selected chat as active
    setIsSharedChat(false); // This is important!
    setShowSearch(false); // Close the search input
  };

  useEffect(() => {
    console.log("chat IIIIIIddddddd");
    console.log(currentChatId);
    const fetchOrSetChat = async () => {
      // Check if the current chat is already in the chats list
      const existingChat = chats.find((chat) => chat.id === currentChatId);
      if (existingChat) {
        setChat(existingChat); // If it's already in the chats list, just set it
        setLoading(false);
        return;
      }
      // If the chat is not found in the list, fetch from the backend
      setLoading(true);
      try {
        const response = await axios.get(
          `${liveURl}/api/chat/shared/${currentChatId}`
        );
        const loadedChat = response.data.chat;
        // Add the loaded chat to the sidebar chats list if it's not already there
        setChats((prevChats) => {
          const exists = prevChats.some((chat) => chat.id === loadedChat._id);
          if (!exists) {
            return [
              ...prevChats,
              {
                id: loadedChat._id,
                name: loadedChat.name || "Shared Chat", // Fallback name if no name provided
                messages: loadedChat.messages,
              },
            ];
          }
          return prevChats;
        });

        // Set the loaded chat as the current chat
        setChat(loadedChat);
      } catch (err) {
        setError("Chat not found or error fetching chat.");
      } finally {
        setLoading(false);
      }
    };
    fetchOrSetChat();
  }, [currentChatId, chats]); // Depend on currentChatId and chats to ensure chat is fetched or updated

  useEffect(() => {
    if (chat?.messages?.length > 0) {
      const userMsgs = chat.messages.filter((msg) => msg.sender === "user");
      setUserMessageCount(userMsgs.length);
    } else {
      setUserMessageCount(0);
    }
  }, [chat]);

  const typeBotMessage = async (text) => {
    const delay = (ms) => new Promise((res) => setTimeout(res, ms));
    let typedText = "";
    for (let i = 0; i < text.length; i++) {
      typedText += text[i];
      setChat((prev) =>
        prev
          ? {
              ...prev,
              messages: prev.messages.map((msg, index, arr) =>
                index === arr.length - 1 && msg.sender === "bot"
                  ? { ...msg, text: typedText }
                  : msg
              ),
            }
          : prev
      );
      await delay(15);
    }
    scrollToBottom();
  };

  const chatLimit = 10;
  const createNewChat = () => {
    if (chats.length >= chatLimit) {
      toast(
        `You've reached your limit of ${chatLimit} chats. Please continue using your existing chats or log in for more.`
      );
      return;
    }
    const newChat = {
      id: Date.now(),
      name: "New Chat",
      messages: [
        {
          sender: "bot",
          text: "Hello! How can I assist you with Canadian immigration?",
        },
      ],
      message: "",
      loading: false,
      isTemp: true,
    };
    setChats([newChat, ...chats]);
    setCurrentChatId(newChat.id);
    // setCurrentChatId(newChatId);
    setIsSharedChat(false); // This is important!
  };

  const handleSearch = (e) => {
    const query = e.target.value.toLowerCase();
    setSearchQuery(query);
    if (query === "") {
      setFilteredChats(chats);
      return;
    }
    const filtered = chats.filter((chat) => {
      const messages = chat?.messages ?? [];
      const firstUserMessage = messages.find((m) => m.sender === "user");
      const isDefaultName =
        !chat.name ||
        chat.name === "New Chat" ||
        /^chat\b|\d{1,2}\/\d{1,2}\/\d{4}/i.test(chat.name);
      const fallbackTitle =
        firstUserMessage?.text?.length > 0
          ? firstUserMessage.text.length > 25
            ? firstUserMessage.text.slice(0, 25) + "..."
            : firstUserMessage.text
          : "New Chat";
      const titleToSearch = isDefaultName ? fallbackTitle : chat.name;
      return titleToSearch.toLowerCase().includes(query);
    });
    setFilteredChats(filtered);
  };

  useEffect(() => {
    if (showSearch) {
      setFilteredChats(chats); // Always refresh chat list on search open
    }
  }, [showSearch, chats]);

  const deleteChat = (id) => {
    const updatedChats = chats.filter((chat) => chat.id !== id);
    setChats(updatedChats);
    if (currentChatId === id && updatedChats.length > 0) {
      setCurrentChatId(updatedChats[0].id);
    } else if (updatedChats.length === 0) {
      createNewChat();
    }
  };

  const handleUserMessage = async () => {
    console.log("dididid212222222");
    console.log(currentChatId);
    if (!messageInput.trim() || userMessageCount >= 3) return;
    const userText = messageInput.trim();
    const userEmail = localStorage.getItem("userEmail");
    const userMsg = { sender: "user", text: userText };
    const updatedCurrentChat = {
      ...chat,
      messages: [...chat.messages, userMsg],
    };
    setChat(updatedCurrentChat);
    setChats((prevChats) =>
      prevChats.map((c) =>
        c.id === updatedCurrentChat.id ? updatedCurrentChat : c
      )
    );
    setMessageInput("");
    setUserMessageCount((count) => count + 1);
    scrollToBottom();
    try {
      setIsTyping(true);
      console.log("dididid");
      console.log(currentChatId);
      const res = await axios.post(`${liveURl}/api/shared/chat`, {
        message: userText,
        chatId: currentChatId, // make sure this always matches `chat.id`
        // userEmail,
      });
      const botText = res.data.response;
      const botMsg = { sender: "bot", text: botText };
      const updatedChatWithBot = {
        ...updatedCurrentChat,
        messages: [...updatedCurrentChat.messages, botMsg],
        isTemp: false, // mark as saved
      };
      setChat(updatedChatWithBot);
      setChats((prevChats) => {
        const updatedChats = prevChats.map((c) =>
          c.id === updatedChatWithBot.id ? updatedChatWithBot : c
        );
        localStorage.setItem("chats", JSON.stringify(updatedChats));
        return updatedChats;
      });
      await typeBotMessage(botText);
    } catch (err) {
      setError("❌ Failed to get response from the bot.");
      console.error(err);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    const currentChat = chats.find((chat) => chat.id === currentChatId);
    if (currentChat) {
      setIsSharedChat(currentChat.isShared || false); // You must mark shared chats with `isShared: true`
    }
  }, [currentChatId, chats]);

  useEffect(() => {
    // Filter out completely empty temporary chats if needed
    const persistentChats = chats.filter((chat) => chat.messages.length > 0);
    localStorage.setItem("chats", JSON.stringify(persistentChats));
  }, [chats]);
  if (loading)
    return <div className="chat-standalone-loading">Loading chat...</div>;
  if (error) return <div className="chat-standalone-error">{error}</div>;
  if (!chat) return <div className="chat-standalone-error">No chat found.</div>;

  return (
    <div className="chat-container">
      <aside className={`sidebarr ${isSidebarOpen ? "open" : "collapsed"}`}>
        <div className="sidebarr-header">
          <div className="sidebar-logo">
            <img src={sidebarimg} alt="Logo" />
          </div>
          <button
            className="toggle-btn"
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          >
            ☰
          </button>
        </div>
        <div className="sidebar-actions">
          <button className="new-chat-btn" onClick={createNewChat}>
            <FiPlus className="plus-icon" />
            {isSidebarOpen && <span className="btn-label">New Chat</span>}
          </button>

          <button className="search-btn" onClick={() => setShowSearch(true)}>
            <FiSearch className="search-icon" />
            {isSidebarOpen && <span className="btn-label">Search</span>}
          </button>
        </div>

        {showSearch && (
          <>
            {/* Background Overlay */}
            <div
              className="search-overlay"
              onClick={() => setShowSearch(false)}
            ></div>

            <div className="search-popup">
              <div className="search-header">
                <h2>Search Chats</h2>
                <button
                  className="close-btn"
                  onClick={() => setShowSearch(false)}
                >
                  <FiX />
                </button>
              </div>

              <div className="search-box">
                <input
                  type="text"
                  placeholder="Search chats..."
                  value={searchQuery}
                  onChange={handleSearch}
                  autoFocus
                />
              </div>

              {/* 🔽 Filtered Chat List Inside Popup */}
              <ul className="search-results">
                {filteredChats.length > 0 ? (
                  filteredChats.map((chat) => (
                    <li key={chat.id} onClick={() => openChat(chat.id)}>
                      {chat.name}
                    </li>
                  ))
                ) : (
                  <li className="no-result">No chats found</li>
                )}
              </ul>
            </div>
          </>
        )}
        {/* </div> */}

        {isSidebarOpen && (
          <>
            <div className="chat-history">
              {chats
                .sort((a, b) => {
                  const aMessages = a?.messages ?? [];
                  const bMessages = b?.messages ?? [];

                  if (aMessages.length === 0) return -1;
                  if (bMessages.length === 0) return 1;
                  return b.id - a.id;
                })
                .map((chat) => {
                  const messages = chat?.messages ?? [];
                  const firstUserMessage = messages.find(
                    (m) => m.sender === "user"
                  );
                  // Title: prefer chat.name, fallback to first user message
                  let title = "New Chat";
                  if (chat.name && chat.name !== "New Chat") {
                    title =
                      chat.name.length > 25
                        ? chat.name.slice(0, 25) + "..."
                        : chat.name;
                  } else if (firstUserMessage?.text) {
                    title =
                      firstUserMessage.text.length > 25
                        ? firstUserMessage.text.slice(0, 25) + "..."
                        : firstUserMessage.text;
                  }

                  return (
                    <div
                      key={chat.id}
                      className={`chat-item ${
                        chat.id === currentChatId ? "active" : ""
                      }`}
                      onClick={() => setCurrentChatId(chat.id)}
                    >
                      <div className="chat-title">{title}</div>
                      <button
                        className="delete-btn"
                        onClick={(e) => {
                          e.stopPropagation();
                          deleteChat(chat.id);
                        }}
                      >
                        <FiTrash className="trash-icon" />
                      </button>
                    </div>
                  );
                })}
            </div>
          </>
        )}
      </aside>

      <div className="chatbox">
        <div className="chatbox-header">
          <div className="profile-container">
            {/* Profile Icon */}
            <div className="headerButton">
              <button className="new-chat-btn-inside" onClick={createNewChat}>
                <FiPlus className="plus-icon-inside" />
              </button>
              <button
                className="search-btn-inside"
                onClick={() => setShowSearch(true)}
              >
                <FiSearch className="search-icon-inside" />
              </button>
            </div>
          </div>
        </div>

        {/* <div className="messages" ref={chatContainerRef}>
          {chat.messages.map((msg, index) => (
            <div key={index} className={`message ${msg.sender}`}>
              <p
                dangerouslySetInnerHTML={{
                  __html: msg.text.replace(/\n/g, "<br />"),
                }}
              ></p>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div> */}

        <div className="messages" ref={chatContainerRef}>
          {chat.messages.map((msg, index) => (
            <div key={index} className={`message ${msg.sender}`}>
              <p
                dangerouslySetInnerHTML={{
                  __html: msg.text.replace(/\n/g, "<br />"),
                }}
              ></p>
            </div>
          ))}

          {isTyping && <div className="message bot thinking">Thinking...</div>}

          <div ref={messagesEndRef} />
        </div>

        {!isAtBottom && (
          <button className="scroll-bottom-btn" onClick={scrollToBottom}>
            ↓
          </button>
        )}

        {!isSharedChat && chat.id ? (
          userMessageCount < 3 ? (
            <div className="input-area">
              <textarea
                value={messageInput}
                disabled={isTyping || userMessageCount >= 3}
                onChange={(e) => setMessageInput(e.target.value)}
                placeholder={
                  isTyping
                    ? "⏳ Let me complete my response..."
                    : "Ask me about Canadian immigration..."
                }
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    if (!isTyping && userMessageCount < 3) {
                      handleUserMessage();
                    }
                  }
                }}
              />

              {messageInput.trim() === "" ? (
                <button
                  className="mic-btn"
                  onClick={() => alert("Mic not available in standalone.")}
                  disabled={isTyping || userMessageCount >= 3}
                >
                  <FiMic size={22} />
                </button>
              ) : (
                <button
                  className="send-btn"
                  onClick={handleUserMessage}
                  disabled={
                    isTyping ||
                    messageInput.trim() === "" ||
                    userMessageCount >= 3
                  }
                >
                  <FiSend size={22} />
                </button>
              )}
            </div>
          ) : (
            <div
              style={{ padding: "1rem", color: "#888", textAlign: "center" }}
            >
              🚫 You've reached your daily message limit. ⏳ You can send
              messages again in 24hr.
            </div>
          )
        ) : (
          <div style={{ padding: "1rem", color: "#888", textAlign: "center" }}>
            You cannot ask here. If you want, then first create a new chat.
          </div>
        )}

        {/* {!isSharedChat ? (
          userMessageCount < 3 ? (
            <div className="input-area">
              <textarea
                value={messageInput}
                disabled={isTyping || userMessageCount >= 3}
                onChange={(e) => setMessageInput(e.target.value)}
                placeholder={
                  isTyping
                    ? "⏳ Let me complete my response..."
                    : "Ask me about Canadian immigration..."
                }
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    if (!isTyping && userMessageCount < 3) {
                      handleUserMessage();
                    }
                  }
                }}
              />

              {messageInput.trim() === "" ? (
                <button
                  className="mic-btn"
                  onClick={() => alert("Mic not available in standalone.")}
                  disabled={isTyping || userMessageCount >= 3}
                >
                  <FiMic size={22} />
                </button>
              ) : (
                <button
                  className="send-btn"
                  onClick={handleUserMessage}
                  disabled={
                    isTyping ||
                    messageInput.trim() === "" ||
                    userMessageCount >= 3
                  }
                >
                  <FiSend size={22} />
                </button>
              )}
            </div>
          ) : (
            <div
              style={{ padding: "1rem", color: "#888", textAlign: "center" }}
            >
              🚫 You've reached your daily message limit. ⏳ You can send
              messages again in 24hr{" "}
            </div>
          )
        ) : (
          <div style={{ padding: "1rem", color: "#888", textAlign: "center" }}>
            you can not ask here. if you want then create new chat.
          </div>
        )} */}

        <p className="developed-by-c">Developed by ParamSolutions.ca</p>
      </div>
    </div>
  );
};

export default Chatstandalone;
