import React from "react";
import { Link } from "react-router-dom";
import "./Cancel.css"; // External CSS for styling

const CancelPage = () => {
  return (
    <div className="cancel-page-container">
      <div className="cancel-card">
        <h1 className="cancel-title">Subscription Canceled</h1>
        <p className="cancel-message">You have canceled the checkout process.</p>
        <Link to="/" className="cancel-home-link">
          ← Go back to Home
        </Link>
      </div>
    </div>
  );
};

export default CancelPage;
