

import React, { useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "./Success.css";

const Success = () => {
  const navigate = useNavigate();

      const liveURl = "https://immigrategpt.ca"
  // const liveURl = "http://localhost:5000"
  
  useEffect(() => {
    const fetchSessionData = async () => {
      const urlParams = new URLSearchParams(window.location.search);
      const sessionId = urlParams.get("session_id");
      const userEmail = localStorage.getItem("userEmail");

      if (sessionId) {
        try {
          // 1. Complete the checkout
          const response = await axios.post(`${liveURl}/api/auth/api/billing/complete-checkout`, {
            sessionId,
          });

          if (response.data.success) {
            // 2. ✅ Fetch updated user plan
            const userResponse = await axios.post(`${liveURl}/api/auth/get-user-by-email`, {
              email: userEmail,
            });

            if (userResponse.data.user?.plan) {
              localStorage.setItem("userPlan", userResponse.data.user.plan);
            }

            alert("Your plan has been successfully upgraded!");
            navigate("/c"); // Redirect to chat page
          }
        } catch (error) {
          console.error("❌ Error completing checkout:", error);
          alert("Something went wrong while completing your checkout.");
        }
      }
    };

    fetchSessionData();
  }, [navigate]);

  return (
    <div className="success-container">
      <h1>Thank you for your purchase!</h1>
      <p>Your plan is being updated...</p>
    </div>
  );
};

export default Success;
