// src/pages/ForgotPassword.js
import React, { useState } from "react";
import axios from "axios";
import "./ForgotPassword.css"; // Import your custom CSS
import loginIllustration from "../../assets/login-illustration.webp";

const ForgotPassword = () => {
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

      const liveURl = "https://immigrategpt.ca"
  // const liveURl = "http://localhost:5000"

  const handleForgotPassword = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post(`${liveURl}/api/auth/forgot-password`, { email });
      setMessage(res.data.message);
      setError("");
      setEmail("")
    } catch (err) {
      setMessage("");
      setError(err.response?.data?.message || "Error sending reset link.");
    }
  };

  return (
    <div className="forgot-password-container">
      {/* Left Side - Forgot Password Form */}
      <div className="forgot-password-box">
        <h2>Forgot Password</h2>
        <form onSubmit={handleForgotPassword}>
          <div className="input-group">
            <input
              type="email"
              placeholder="Enter your registered email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="forgot-password-btn">
            Send Reset Link
          </button>
        </form>
        {message && <p className="success-message">{message}</p>}
        {error && <p className="error-message">{error}</p>}
      </div>

      {/* Right Side - Image & Info */}
      <div className="forgot-password-info">
        <h1>Need Help Logging In?</h1>
        <p>Enter your email and we'll send you a reset link.</p>
        <img src={loginIllustration} alt="Forgot password illustration" />
      </div>
    </div>
  );
};

export default ForgotPassword;
