import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./Signup.css";
import signupIllustration from "../assets/signup-illustration.png";
import { FiEye, FiEyeOff } from "react-icons/fi";
import { FaGoogle, FaLinkedin, FaFacebook, FaMicrosoft } from "react-icons/fa";
import ReCAPTCHA from "react-google-recaptcha";

const Signup = () => {
  const [formData, setFormData] = useState({
    name: "",
    mobile: "",
    email: "",
    password: "",
  });

  const liveURl = "https://immigrategpt.ca";
  // const liveURl = "http://localhost:5000"

  const [formErrors, setFormErrors] = useState({});
  const [error, setError] = useState("");
  const [recaptchaToken, setRecaptchaToken] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const error = params.get("error");
    if (error) console.log("❌ Signup error from OAuth:", error);
  }, []);

  useEffect(() => {
    const token = localStorage.getItem("userEmail");
    const otpverify = localStorage.getItem("OTPVerified");
    if (token && otpverify) navigate("/c");
  }, [navigate]);

  const validate = () => {
    const errors = {};

    const rawMobile = formData.mobile.trim();
    const cleanedMobile = rawMobile.replace(/\D/g, ""); // Remove non-digit characters

    const nameRegex = /^[A-Za-z\s]+$/;
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const strongPasswordRegex =
      /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*#?&]).{8,}$/;

    // Name
    if (!formData.name.trim()) {
      errors.name = "Name is required";
    } else if (!nameRegex.test(formData.name.trim())) {
      errors.name = "Name should contain only letters and spaces";
    }

    // Mobile
    if (!rawMobile) {
      errors.mobile = "Mobile number is required";
    } else if (cleanedMobile.length !== 10) {
      errors.mobile = "Mobile number must be 10 digits";
    } else if (!/^[2-9]\d{2}[2-9]\d{6}$/.test(cleanedMobile)) {
      errors.mobile = "Enter a valid 10-digit Canadian mobile number";
    }

    // Email
    if (!formData.email.trim()) {
      errors.email = "Email is required";
    } else if (!emailRegex.test(formData.email)) {
      errors.email = "Please enter a valid email address";
    }

    // Password
    if (!formData.password) {
      errors.password = "Password is required";
    } else if (!strongPasswordRegex.test(formData.password)) {
      errors.password =
        "Password must be 8+ characters with upper, lower, number, and symbol";
    }

    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setFormErrors((prev) => ({ ...prev, [e.target.name]: "" }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    if (!validate()) return;

    if (!recaptchaToken) {
      setError("Please complete the CAPTCHA.");
      return;
    }

    try {
      const response = await axios.post(`${liveURl}/api/auth/signup`, {
        ...formData,
        recaptchaToken,
      });

      // console.log("Signup successful", response.data);
      localStorage.setItem("authToken", response.data.token);
      localStorage.setItem("userEmail", formData.email);

      const userResponse = await axios.get(`${liveURl}/api/auth/userinfo`, {
        headers: {
          Authorization: `Bearer ${response.data.token}`,
        },
        params: {
          email: formData.email, // 👈 your query parameter here
        },
      });

      const userPlan = userResponse.data.plan || "Free";
      // const userPlan = userResponse.data.plan;
      localStorage.setItem("userPlan", userPlan);


      navigate("/otpverify");
    } catch (error) {
      if (error.response) {
        setError(error.response.data.message || "Something went wrong.");
      } else if (error.request) {
        setError("No response from server. Please check your connection.");
      } else {
        setError("An error occurred. Please try again.");
      }
      console.error("Signup error:", error);
    }
  };

  return (
    <div className="signup-container">
      <div className="signup-box">
        <h2>Sign Up</h2>
        {error && <p className="error-msg">{error}</p>}

        <form onSubmit={handleSubmit}>
          <div className="input-group">
            <label>Name</label>
            <input
              type="text"
              name="name"
              placeholder="Enter your name"
              value={formData.name}
              onChange={handleChange}
            />
            {formErrors.name && (
              <p className="field-error">{formErrors.name}</p>
            )}
          </div>

          <div className="input-group">
            <label>Mobile</label>
            <input
              type="text"
              name="mobile"
              placeholder="Enter your mobile number"
              value={formData.mobile}
              onChange={handleChange}
            />
            {formErrors.mobile && (
              <p className="field-error">{formErrors.mobile}</p>
            )}
          </div>

          <div className="input-group">
            <label>Email</label>
            <input
              type="email"
              name="email"
              placeholder="Enter your email"
              value={formData.email}
              onChange={handleChange}
            />
            {formErrors.email && (
              <p className="field-error">{formErrors.email}</p>
            )}
          </div>

          <div className="input-group password-group">
            <label>Password</label>
            <div className="password-wrapper">
              <input
                type={showPassword ? "text" : "password"}
                name="password"
                placeholder="Enter your password"
                value={formData.password}
                onChange={handleChange}
              />
              <span
                className="toggle-password"
                onClick={() => setShowPassword((prev) => !prev)}
              >
                {showPassword ? <FiEyeOff /> : <FiEye />}
              </span>
            </div>
            {formErrors.password && (
              <p className="field-error">{formErrors.password}</p>
            )}
          </div>

          <ReCAPTCHA
            sitekey="6LeNsnsrAAAAAKHoSgGLz5SS_TPRYfF2J39RrlLM"
            onChange={(token) => setRecaptchaToken(token)}
          />

          <button type="submit" className="signup-btn">
            Get Started
          </button>

          <p className="login-link">
            Already have an account? <a href="/login">Log in</a>
          </p>
        </form>

        <div className="social-login">
          <button
            className="google-btn"
            onClick={() =>
              (window.location.href =
                "https://www.immigrategpt.ca/api/auth/google")
            }
            title="Login with Google"
          >
            <FaGoogle size={20} />
          </button>

          <button
            className="linkedin-btn"
            onClick={() =>
              (window.location.href =
                "https://www.immigrategpt.ca/api/auth/linkedin")
            }
            title="Login with LinkedIn"
          >
            <FaLinkedin size={20} />
          </button>

          <button
            className="facebook-btn"
            onClick={() =>
              (window.location.href =
                "https://www.immigrategpt.ca/api/auth/facebook")
            }
            title="Login with Facebook"
          >
            <FaFacebook size={20} />
          </button>

          <button
            className="microsoft-btn"
            onClick={() =>
              (window.location.href =
                "https://www.immigrategpt.ca/api/auth/microsoft")
            }
            title="Login with Microsoft"
          >
            <FaMicrosoft size={20} />
          </button>
        </div>
      </div>

      <div className="signup-info">
        <h1>Welcome to AI Chat</h1>
        <p>
          Join now and start your journey with our AI-powered chat experience.
        </p>
        <img src={signupIllustration} alt="Chat AI Illustration" />
      </div>

      <p className="developed-by">Developed by ParamSolutions.ca</p>
    </div>
  );
};

export default Signup;
