import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./Developertoken.css"; // Updated CSS
import loginIllustration from "../assets/login-illustration.webp";
import { FiEye, FiEyeOff } from "react-icons/fi";

const Developertoken = () => {
  const [formData, setFormData] = useState({
    developertoken: "",
  });

      const liveURl = "https://immigrategpt.ca"
  // const liveURl = "http://localhost:5000"

  const [error, setError] = useState("");
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);
  // 🔥 Check if user is already logged in
  useEffect(() => {
    const token = localStorage.getItem("userEmail");
    if (!token) {
      navigate("/login");
    }
  }, [navigate]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    const userEmail = localStorage.getItem("userEmail");
    if (!userEmail) {
      setError("User not logged in.");
      return;
    }

    try {
      const response = await axios.post(`${liveURl}/api/user/saveDeveloperToken`,{
          userEmail,
          token: formData.developertoken,
        }
      );

      if (response.data.success) {
        alert("Token saved! You now have developer access for 1 month.");
        navigate("/c"); // or wherever you want to go
      } else {
        setError(response.data.message || "Invalid token.");
      }
    } catch (err) {
      console.error(err);
      setError("Something went wrong. Please try again.");
    }
  };

  return (
    <div className="login-container">
      {/* Left Side - Login Form */}
      <div className="login-box">
        <h2>Test with Developers</h2>
        {error && <p className="error-msg">{error}</p>}
        <form onSubmit={handleSubmit}>
          <div className="input-group">
            <label>Token</label>
            <input
              type="text"
              name="developertoken"
              placeholder="Enter your email"
              value={formData.developertoken}
              onChange={handleChange}
              required
            />
          </div>

          <button type="submit" className="login-btn">
            Take 1 month test
          </button>
        </form>
      </div>

      <p className="developed-by">Developed by ParamSolutions.ca</p>

      {/* Right Side - Image & Text */}
      <div className="login-info">
        <h1>Welcome to AI Chat</h1>
        <p>
          Join now and start your journey with our AI-powered chat experience.
        </p>
        <img src={loginIllustration} alt="Chat AI Illustration" />
      </div>
    </div>
  );
};

export default Developertoken;
