import React, { useState } from "react";
import "./SettingsPopup.css";
import {
  FiX,
  FiUser,
  FiSettings,
  FiKey,
  FiHelpCircle,
  FiMoon,
  FiSun,
  FiMonitor,
} from "react-icons/fi";
import { MdWorkspacePremium } from "react-icons/md";

export default function SettingsPopup({
  onClose,
  userInfo,
  onDeleteAllChats,
  onDeleteAccount,
  currentTheme,
  onThemeChange,
  // selectedLanguage, // ✅ add this
  // onLanguageChange, // ✅ add this
}) {
  const [activeTab, setActiveTab] = useState("general");

  return (
    <div className="settings-overlay">
      <div className="settings-modal">
        {/* Sidebar */}
        <div className="settings-sidebar">
          <h2>Settings</h2>
          <ul>
            <li
              className={activeTab === "general" ? "active" : ""}
              onClick={() => setActiveTab("general")}
            >
              <FiSettings /> General
            </li>
            <li
              className={activeTab === "account" ? "active" : ""}
              onClick={() => setActiveTab("account")}
            >
              <FiUser /> Account
            </li>
            <li
              className={activeTab === "plan" ? "active" : ""}
              onClick={() => setActiveTab("plan")}
            >
              <MdWorkspacePremium /> My Plan
            </li>
            <li
              className={activeTab === "api" ? "active" : ""}
              onClick={() => setActiveTab("api")}
            >
              <FiKey /> API Keys
            </li>
            <li
              className={activeTab === "help" ? "active" : ""}
              onClick={() => setActiveTab("help")}
            >
              <FiHelpCircle /> Help
            </li>
          </ul>
        </div>

        {/* Content Area */}
        <div className="settings-content">
          <button className="close-btn" onClick={onClose}>
            <FiX />
          </button>

          {activeTab === "general" && (
            <div className="general-settings">
              <h3>Theme</h3>
              <div className="theme-options">
                <button
                  className={`theme-btn ${
                    currentTheme === "light" ? "selected" : ""
                  }`}
                  onClick={() => onThemeChange("light")}
                >
                  <FiSun /> Light
                </button>
                <button
                  className={`theme-btn ${
                    currentTheme === "dark" ? "selected" : ""
                  }`}
                  onClick={() => onThemeChange("dark")}
                >
                  <FiMoon /> Dark
                </button>
                <button
                  className={`theme-btn ${
                    currentTheme === "system" ? "selected" : ""
                  }`}
                  onClick={() => onThemeChange("system")}
                >
                  <FiMonitor /> System
                </button>
              </div>

              <hr />

              {/* <h3>Danger Zone</h3>
              <button className="danger-btn" onClick={onDeleteAllChats}>
                Delete All Chats
              </button> */}
              <div className="danger-zone-row">
                <h3>Danger Zone</h3>
                <button className="danger-btn" onClick={onDeleteAllChats}>
                  Delete All Chats
                </button>
              </div>

              <hr />

<div className="danger-zone-row">
                <h3>Delete Account</h3>
                <button className="danger-btn" onClick={onDeleteAccount}>
                  Delete Account
                </button>
              </div>
              {/* <div className="danger-zone-row">
                <h3>Voice Language</h3>
                <select
                  className="language-select"
                  value={selectedLanguage}
                  onChange={(e) => onLanguageChange(e.target.value)}
                >
                  <option value="en-US">English (US)</option>
                  <option value="en-GB">English (UK)</option>
                  <option value="hi-IN">Hindi (India)</option>
                  <option value="fr-FR">French</option>
                  <option value="es-ES">Spanish</option>
                  <option value="de-DE">German</option>
                  <option value="ja-JP">Japanese</option>
                  <option value="zh-CN">Chinese</option>
                </select>
              </div> */}
            </div>
          )}

          {activeTab === "account" && (
            <div className="user-info">
              <h3>{userInfo.name}</h3>
              <p>{userInfo.email}</p>
              <p>Current Plan: {userInfo.plan}</p>
            </div>
          )}

          {activeTab === "plan" && (
            <div>
              <h3>My Plan</h3>
              <p>
                You are currently on the <strong>{userInfo.plan}</strong> plan.
              </p>
            </div>
          )}

          {activeTab === "api" && (
            <div>
              <h3>API Keys</h3>
              <p>Manage and regenerate your API keys here.</p>
            </div>
          )}

          {activeTab === "help" && (
            <div>
              <h3>Help Center</h3>
              <p>FAQs and support resources coming soon.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
