import React, { useState, useEffect } from "react";
import "./GenerateQuestions.css";
import toast, { Toaster } from "react-hot-toast";

const GenerateQuestions = () => {
  const [formData, setFormData] = useState({
    topic: "immigration",
    sourceType: "google",
  });
  const [loading, setLoading] = useState(false);
  const [questions, setQuestions] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showCard, setShowCard] = useState(true);
  const [timeLeft, setTimeLeft] = useState(60);
  const [allTests, setAllTests] = useState([]);
  const [modalOpen, setModalOpen] = useState(false);
  const [error, setError] = useState("");

  const [fromGenerated, setFromGenerated] = useState(false);

    const liveURl = "https://immigrategpt.ca"
  // const liveURl = "http://localhost:5000"

  useEffect(() => {
    let timer;
    if (showCard && timeLeft > 0) {
      timer = setTimeout(() => setTimeLeft((prev) => prev - 1), 1000);
    } else if (timeLeft === 0) {
      setShowCard(false);
    }
    return () => clearTimeout(timer);
  }, [showCard, timeLeft]);

  useEffect(() => {
    const fetchAllTests = async () => {
      try {
        const res = await fetch(
          `${liveURl}/api/examination/all-tests`
          // "https://immigrategpt.ca/api/examination/all-tests"
        );
        const data = await res.json();
        if (data.success) {
          setAllTests(data.tests);
        } else {
          console.error("Failed to load tests");
        }
      } catch (err) {
        console.error("Error fetching tests:", err);
      }
    };

    fetchAllTests();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // const handleSubmit = async (e) => {
  //   e.preventDefault();
  //   setError("");
  //   setQuestions([]);
  //   setLoading(true);

  //   try {
  //     const response = await fetch(
  //       "https://immigrategpt.ca/api/examination/generate-questions",
  //       {
  //         method: "POST",
  //         headers: { "Content-Type": "application/json" },
  //         body: JSON.stringify({
  //           topic: formData.topic,
  //           sourceType: formData.sourceType,
  //           url: formData.url,
  //         }),
  //       }
  //     );

  //     const data = await response.json();

  //     if (data && data.doc) {
  //       const newQuestions = data.doc.questions || [];
  //       setQuestions(newQuestions.slice(-10));
  //       toast.success("✅ Questions generated successfully!");

  //       setAllTests((prevTests) => [
  //         ...prevTests,
  //         {
  //           topic: formData.topic,
  //           totalQuestions: newQuestions.length,
  //           createdAt: new Date(),
  //         },
  //       ]);

  //       setCurrentIndex(0);
  //       setShowCard(true);
  //       setTimeLeft(60);
  //     } else {
  //       setError("No questions generated.");
  //     }
  //   } catch (err) {
  //     console.error("❌ Request failed:", err);
  //     setError("Something went wrong. Please try again later.");
  //   } finally {
  //     setLoading(false);
  //   }
  // };
  const handleSubmit = async (e) => {
  e.preventDefault();
  setError("");
  setQuestions([]);
  setLoading(true);
  setFromGenerated(true);   // ✅ This is important
  setModalOpen(false);      // Just in case any modal is open
  setShowCard(true);        // Still show main card

  try {
    const response = await fetch(
      `${liveURl}/api/examination/generate-questions`,
      // "https://immigrategpt.ca/api/examination/generate-questions",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          topic: formData.topic,
          sourceType: formData.sourceType,
          url: formData.url,
        }),
      }
    );

    const data = await response.json();

    if (data && data.doc) {
      const newQuestions = data.doc.questions || [];
      setQuestions(newQuestions.slice(-10));
      toast.success("✅ Questions generated successfully!");

      setAllTests((prevTests) => [
        ...prevTests,
        {
          topic: formData.topic,
          totalQuestions: newQuestions.length,
          createdAt: new Date(),
        },
      ]);

      setCurrentIndex(0);
      setShowCard(true);
      setTimeLeft(60);
    } else {
      setError("No questions generated.");
    }
  } catch (err) {
    console.error("❌ Request failed:", err);
    setError("Something went wrong. Please try again later.");
  } finally {
    setLoading(false);
  }
};

const handleCardClick = async (topic) => {
  try {
    const res = await fetch(
      `https://immigrategpt.ca/api/examination/get-test-by-topic/${topic}`
    );
    const data = await res.json();
    if (data && data.questions) {
      setFromGenerated(false); // ⛔ Don't show timed question card
      setShowCard(false);      // hide generated card
      setQuestions(data.questions);
      setCurrentIndex(0);
      setModalOpen(true);      // ✅ Show modal instead
    } else {
      toast.error("❌ No questions found for this topic.");
    }
  } catch (err) {
    console.error(err);
    toast.error("❌ Failed to load questions.");
  }
};


  // const handleCardClick = async (topic) => {
  //   try {
  //     const res = await fetch(
  //       `https://immigrategpt.ca/api/examination/get-test-by-topic/${topic}`
  //     );
  //     const data = await res.json();
  //     if (data && data.questions) {
  //       setQuestions(data.questions);
  //       setCurrentIndex(0);
  //       setModalOpen(true);
  //     } else {
  //       toast.error("❌ No questions found for this topic.");
  //     }
  //   } catch (err) {
  //     console.error(err);
  //     toast.error("❌ Failed to load questions.");
  //   }
  // };

  return (
    <>
      <Toaster position="top-center" reverseOrder={false} />
      <div className="generate-questions-container">
        <h2>Generate Questions</h2>
        {error && <p className="error-msg">{error}</p>}

        <form onSubmit={handleSubmit}>
          <div className="input-group">
            <label>Topic</label>
            <select name="topic" value={formData.topic} onChange={handleChange}>
              <option value="immigration">Immigration</option>
              <option value="canada study permit">Canada Study Permit</option>
              <option value="work">Work</option>
              <option value="express entry">Express Entry</option>
              <option value="permanent residency">Permanent Residency</option>
              <option value="visitor visa">Visitor Visa</option>
              <option value="post graduate work permit">
                Post Graduate Work Permit
              </option>
              <option value="lmia">LMIA</option>
              <option value="open work permit">Open Work Permit</option>
              <option value="provincial nominee program">PNP</option>
              <option value="citizenship">Canadian Citizenship</option>
              <option value="refugee">Refugee</option>
              <option value="family sponsorship">Family Sponsorship</option>
              <option value="spousal sponsorship">Spousal Sponsorship</option>
              <option value="rural and northern immigration pilot">RNIP</option>
              <option value="atlantic immigration program">
                Atlantic Program
              </option>
              <option value="startup visa">Start-up Visa</option>
              <option value="super visa">Super Visa</option>
            </select>
          </div>

          <div className="input-group">
            <label>Source Type</label>
            <select
              name="sourceType"
              value={formData.sourceType}
              onChange={handleChange}
            >
              <option value="google">Google Search</option>
              <option value="url">Provide URL manually</option>
            </select>
          </div>

          {formData.sourceType === "url" && (
            <div className="input-group">
              <label>URL</label>
              <input
                type="text"
                name="url"
                placeholder="https://example.com/page"
                value={formData.url || ""}
                onChange={handleChange}
                required
              />
            </div>
          )}

          <button type="submit" disabled={loading}>
            {loading ? "Generating..." : "Generate Questions"}
          </button>
        </form>

        {questions.length > 0 && showCard && fromGenerated &&  (
          <div className="question-wrapper">
            <div className="question-controls">
              <button
                className="arrow-btn"
                onClick={() => setCurrentIndex((prev) => Math.max(prev - 1, 0))}
                disabled={currentIndex === 0}
              >
                ⬅
              </button>

              <div className="timer-display">Generated Questions</div>
              <div className="timer-display">
                This is hide in {timeLeft}s. it's Temporarily shown.
              </div>

              <button
                className="arrow-btn"
                onClick={() =>
                  setCurrentIndex((prev) =>
                    Math.min(prev + 1, questions.length - 1)
                  )
                }
                disabled={currentIndex === questions.length - 1}
              >
                ➡
              </button>
            </div>

            {/* <div className="question-controls">
              <button onClick={() => setCurrentIndex((prev) => Math.max(prev - 1, 0))} disabled={currentIndex === 0}>
                ⬅
              </button>
              <div className="timer-display">Generated Questions</div>
              <div className="timer-display">This will hide in {timeLeft}s</div>
              <button
                onClick={() => setCurrentIndex((prev) => Math.min(prev + 1, questions.length - 1))}
                disabled={currentIndex === questions.length - 1}
              >
                ➡
              </button>
            </div> */}
            <div className="question-card">
              <p>
                <strong>Q{currentIndex + 1}:</strong>{" "}
                {questions[currentIndex].question}
              </p>
              <ul>
                {questions[currentIndex].options.map((opt, idx) => (
                  <li
                    key={idx}
                    style={{
                      fontWeight:
                        opt === questions[currentIndex].answer
                          ? "bold"
                          : "normal",
                      color:
                        opt === questions[currentIndex].answer
                          ? "#3c76ff"
                          : "#ffffff",
                      backgroundColor: "#2b2d31",
                      borderRadius: "6px",
                      padding: "8px 12px",
                      marginBottom: "6px",
                    }}
                  >
                    {opt}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        )}
      </div>

      {/* 🧠 Grid of Test Cards */}
      {allTests.length > 0 && (
        <div className="test-grid">
          {allTests.map((test, idx) => (
            <div
              className="test-card"
              key={idx}
              onClick={() => handleCardClick(test.topic)}
            >
              <h4>{test.topic}</h4>
              <p>{test.totalQuestions} Questions</p>
              <small>🕒 {new Date(test.createdAt).toLocaleString()}</small>
            </div>
          ))}
        </div>
      )}

      {/* ✅ Question Modal (No Timer) */}
      {modalOpen && (
        <div className="modal-overlay">
          <div className="modal-content">
            <button className="modal-close" onClick={() => setModalOpen(false)}>
              ❌
            </button>
            {questions.length > 0 && (
              <div className="question-wrapper">
                {/* <div className="question-controls">
                  <button
                    onClick={() =>
                      setCurrentIndex((prev) => Math.max(prev - 1, 0))
                    }
                    disabled={currentIndex === 0}
                  >
                    ⬅
                  </button>
                  <div className="timer-display">
                    Q{currentIndex + 1} of {questions.length}
                  </div>
                  <button
                    onClick={() =>
                      setCurrentIndex((prev) =>
                        Math.min(prev + 1, questions.length - 1)
                      )
                    }
                    disabled={currentIndex === questions.length - 1}
                  >
                    ➡
                  </button>
                </div> */}
                <div className="question-controls">
              <button
                className="arrow-btn"
                onClick={() => setCurrentIndex((prev) => Math.max(prev - 1, 0))}
                disabled={currentIndex === 0}
              >
                ⬅
              </button>

              <div className="timer-display">Generated Questions</div>
              <div className="timer-display">
                This is hide in {timeLeft}s. it's Temporarily shown.
              </div>

              <button
                className="arrow-btn"
                onClick={() =>
                  setCurrentIndex((prev) =>
                    Math.min(prev + 1, questions.length - 1)
                  )
                }
                disabled={currentIndex === questions.length - 1}
              >
                ➡
              </button>
            </div>
                <div className="question-card">
                  <p>
                    <strong>Q{currentIndex + 1}:</strong>{" "}
                    {questions[currentIndex].question}
                  </p>
                  <ul>
                    {questions[currentIndex].options.map((opt, idx) => (
                      <li
                        key={idx}
                        style={{
                          fontWeight:
                            opt === questions[currentIndex].answer
                              ? "bold"
                              : "normal",
                          color:
                            opt === questions[currentIndex].answer
                              ? "#3c76ff"
                              : "#ffffff",
                          backgroundColor: "#2b2d31",
                          borderRadius: "6px",
                          padding: "8px 12px",
                          marginBottom: "6px",
                        }}
                      >
                        {opt}
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      <div
        style={{
          textAlign: "center",
          marginTop: "30px",
          fontSize: "0.9rem",
          color: "#777",
        }}
      >
        Developed by <strong>paramsolutions.cs</strong>
      </div>
    </>
  );
};

export default GenerateQuestions;
